add_action( 'admin_bar_menu', 'perfectpixel_change_howdy_text', 9999 );

function perfectpixel_change_howdy_text( $wp_admin_bar ) {
	$node = $wp_admin_bar->get_node( 'my-account' );
	if ( ! $node || ! is_string( $node->title ) ) {
		return;
	}
	// The title is "<greeting> <span class="display-name">Name</span><avatar>", in any language.
	$pos = strpos( $node->title, '<span class="display-name">' );
	if ( false === $pos ) {
		return;
	}
	$wp_admin_bar->add_node(
		array(
			'id'    => 'my-account',
			'title' => esc_html( '{{admin_bar_greeting}}' ) . ' ' . substr( $node->title, $pos ),
		)
	);
}
